  "card-s7__field__deck": {
   "en": "The inaugural doubles competition split more than 50 pairs across men's and women's divisions in a nine-station hybrid workout, with Somos Uma Vibe and Caracóis da Aldeia topping the leaderboards.",
   "pt": "A competição inaugural de duplas juntou mais de 50 equipas nos escalões masculino e feminino num treino híbrido de nove estações, com as vitórias a ficarem para a Somos Uma Vibe e os Caracóis da Aldeia.",
   "es": "La competición inaugural de parejas reunió a más de 50 equipos en las categorías masculina y femenina en un entrenamiento híbrido de nueve estaciones, con victorias para Somos Uma Vibe y Caracóis da Aldeia.",
   "fr": "La compétition inaugurale en binômes a rassemblé plus de 50 équipes réparties dans les catégories masculine et féminine pour un entraînement hybride à neuf ateliers, remporté par Somos Uma Vibe et Caracóis da Aldeia.",
   "it": "La competizione inaugurale a coppie ha riunito più di 50 team nelle categorie maschile e femminile per un allenamento ibrido a nove stazioni, vinto da Somos Uma Vibe e Caracóis da Aldeia."
  },
