  "a11-title": {
   "en": "Leixões and Benjamin Kanuric Agree to Contract Termination",
   "pt": "Leixões E Benjamin Kanuric Chegam A Acordo Para Rescisão De Contrato",
   "es": "Leixões Y Benjamin Kanuric Acuerdan La Rescisión Del Contrato",
   "fr": "Leixões Et Benjamin Kanuric S'Accordent Sur La Résiliation Du Contrat",
   "it": "Leixões E Benjamin Kanuric Trovano L'Accordo Per La Risoluzione Del Contratto"
  },
  "a11-deck": {
   "en": "The Austrian midfielder leaves Estádio do Mar by mutual agreement, closing his spell at the club with 16 official appearances, three goals and two assists.",
   "pt": "O médio austríaco deixa o Estádio do Mar por mútuo acordo, encerrando a sua passagem pelo clube com 16 jogos oficiais, três golos e duas assistências.",
   "es": "El centrocampista austríaco deja el Estádio do Mar de mutuo acuerdo, cerrando su etapa en el club con 16 partidos oficiales, tres goles y dos asistencias.",
   "fr": "Le milieu de terrain autrichien quitte l'Estádio do Mar d'un commun accord, mettant fin à son passage au club avec 16 matches officiels, trois buts et deux passes décisives.",
   "it": "Il centrocampista austriaco lascia l'Estádio do Mar di comune accordo, chiudendo la sua esperienza al club con 16 presenze ufficiali, tre gol e due assist."
  },
  "a11-byline": {
   "en": "By Image Media News Staff — Matosinhos",
   "pt": "Por Image Media News Staff — Matosinhos",
   "es": "Por Image Media News Staff — Matosinhos",
   "fr": "Par Image Media News Staff — Matosinhos",
   "it": "Di Image Media News Staff — Matosinhos"
  },
  "a11-hero-credit": {
   "en": "Photo: Eduardo Castro",
   "pt": "Foto: Eduardo Castro",
   "es": "Foto: Eduardo Castro",
   "fr": "Photo : Eduardo Castro",
   "it": "Foto: Eduardo Castro"
  },
  "a11-p1": {
   "en": "Leixões SC confirmed on July 30 that it has reached a friendly agreement with Benjamin Kanuric to terminate his contract, closing the Austrian midfielder's spell at Estádio do Mar just over a year after he arrived at the club.",
   "pt": "O Leixões SC confirmou a 30 de julho que chegou a um acordo amigável com Benjamin Kanuric para rescindir o seu contrato, encerrando a passagem do médio austríaco pelo Estádio do Mar pouco mais de um ano após a sua chegada ao clube.",
   "es": "El Leixões SC confirmó el 30 de julio que ha llegado a un acuerdo amistoso con Benjamin Kanuric para rescindir su contrato, poniendo fin a la etapa del centrocampista austríaco en el Estádio do Mar poco más de un año después de su llegada al club.",
   "fr": "Le Leixões SC a confirmé le 30 juillet être parvenu à un accord à l'amiable avec Benjamin Kanuric pour résilier son contrat, mettant fin au passage du milieu de terrain autrichien à l'Estádio do Mar un peu plus d'un an après son arrivée au club.",
   "it": "Il Leixões SC ha confermato il 30 luglio di aver raggiunto un accordo amichevole con Benjamin Kanuric per la risoluzione del contratto, chiudendo l'esperienza del centrocampista austriaco all'Estádio do Mar poco più di un anno dopo il suo arrivo al club."
  },
  "a11-p2": {
   "en": "Kanuric, 22, joined Leixões in July 2025 from Ingolstadt in Germany's third tier, having come through Rapid Vienna's academy before a spell in the German lower leagues that also took in Arminia Bielefeld. He is a former Austria youth international, having featured at the 2022 U19 European Championship.",
   "pt": "Kanuric, de 22 anos, chegou ao Leixões em julho de 2025 vindo do Ingolstadt, da terceira divisão alemã, tendo passado pela formação do Rapid Viena antes de uma passagem pelas ligas inferiores alemãs que incluiu também o Arminia Bielefeld. É antigo internacional austríaco de sub-19, tendo participado no Europeu de Sub-19 de 2022.",
   "es": "Kanuric, de 22 años, llegó al Leixões en julio de 2025 procedente del Ingolstadt, de la tercera división alemana, tras pasar por la cantera del Rapid de Viena antes de una etapa en las ligas inferiores alemanas que incluyó también al Arminia Bielefeld. Es antiguo internacional austríaco sub-19, habiendo disputado la Eurocopa sub-19 de 2022.",
   "fr": "Kanuric, 22 ans, avait rejoint le Leixões en juillet 2025 en provenance de l'Ingolstadt, en troisième division allemande, après être passé par le centre de formation du Rapid Vienne puis par les divisions inférieures allemandes, notamment l'Arminia Bielefeld. Il est ancien international autrichien U19, ayant disputé l'Euro U19 2022.",
   "it": "Kanuric, 22 anni, era arrivato al Leixões nel luglio 2025 dall'Ingolstadt, terza serie tedesca, dopo essere cresciuto nel settore giovanile del Rapid Vienna e aver giocato nelle serie minori tedesche, tra cui l'Arminia Bielefeld. È un ex nazionale austriaco Under 19, avendo disputato l'Europeo Under 19 del 2022."
  },
  "a11-stat": {
   "en": "16 official appearances · 3 goals · 2 assists",
   "pt": "16 jogos oficiais · 3 golos · 2 assistências",
   "es": "16 partidos oficiales · 3 goles · 2 asistencias",
   "fr": "16 matches officiels · 3 buts · 2 passes décisives",
   "it": "16 presenze ufficiali · 3 gol · 2 assist"
  },
  "a11-p3": {
   "en": "Across the 2025/26 season the midfielder made 16 official appearances for the Liga Portugal 2 side, scoring three goals and adding two assists, without fully establishing himself in a competitive Leixões midfield.",
   "pt": "Ao longo da época 2025/26, o médio fez 16 jogos oficiais pela equipa da Liga Portugal 2, marcando três golos e somando duas assistências, sem se afirmar totalmente num meio-campo competitivo do Leixões.",
   "es": "A lo largo de la temporada 2025/26, el centrocampista disputó 16 partidos oficiales con el equipo de la Liga Portugal 2, marcando tres goles y sumando dos asistencias, sin llegar a consolidarse plenamente en un centro del campo competitivo del Leixões.",
   "fr": "Au cours de la saison 2025/26, le milieu de terrain a disputé 16 matches officiels avec l'équipe de Liga Portugal 2, inscrivant trois buts et délivrant deux passes décisives, sans parvenir à s'imposer pleinement dans un entrejeu très disputé au Leixões.",
   "it": "Nel corso della stagione 2025/26, il centrocampista ha collezionato 16 presenze ufficiali con la squadra di Liga Portugal 2, segnando tre gol e fornendo due assist, senza riuscire ad affermarsi pienamente in un centrocampo competitivo del Leixões."
  },
  "a11-p4": {
   "en": "Image Media covered Leixões throughout last season, with photographer Eduardo Castro capturing Kanuric in action at Estádio do Mar across the campaign.",
   "pt": "A Image Media acompanhou o Leixões ao longo da última época, com o fotógrafo Eduardo Castro a captar Kanuric em ação no Estádio do Mar ao longo da temporada.",
   "es": "Image Media siguió al Leixões a lo largo de la última temporada, con el fotógrafo Eduardo Castro captando a Kanuric en acción en el Estádio do Mar durante toda la campaña.",
   "fr": "Image Media a suivi le Leixões tout au long de la dernière saison, le photographe Eduardo Castro ayant photographié Kanuric en action à l'Estádio do Mar tout au long de la campagne.",
   "it": "Image Media ha seguito il Leixões per tutta la scorsa stagione, con il fotografo Eduardo Castro che ha immortalato Kanuric in azione all'Estádio do Mar durante l'intera annata."
  },
